        if a is None and b is None:
            return (None, None)
        if a is None:
            return (b, None)
        if b is None:
            return (a, None)
        s = self.new_var()
        c = self.new_var()
        # sum = a xor b
        self.add_clause([a, b, -s])
        self.add_clause([-a, -b, -s])
        self.add_clause([a, -b, s])
        self.add_clause([-a, b, s])
        # carry = a and b
        self.add_clause([-a, -b, c])
        self.add_clause([a, -c])
        self.add_clause([b, -c])
        return (s, c)

    def or_gate(self, a: Optional[int], b: Optional[int]) -> Optional[int]:
        """Return variable representing a ∨ b (or constant)."""
        if a is None and b is None:
            return None
        if a is None:
            return b
        if b is None:
            return a
        o = self.new_var()
        self.add_clause([-a, o])
        self.add_clause([-b, o])
        self.add_clause([a, b, -o])
        return o

    def full_adder(self, a: Optional[int], b: Optional[int], cin: Optional[int]) -> Tuple[Optional[int], Optional[int]]:
        """Return (sum, carry) for a + b + cin.
        ``None`` denotes constant False.
        """
        sum1, carry1 = self.half_adder(a, b)
        sum_out, carry2 = self.half_adder(sum1, cin)
        carry_out = self.or_gate(carry1, carry2)
        return (sum_out, carry_out)

    # ---------------------------------------------------------------------
    # Utility to force a variable to True/False (or constant)
    # ---------------------------------------------------------------------
    def force_true(self, v: Optional[int]) -> None:
        if v is None:
            self.add_clause([])  # unsatisfiable clause
        else:
            self.add_clause([v])

    def force_false(self, v: Optional[int]) -> None:
        if v is None:
            return
        else:
            self.add_clause([-v])


def reduce(instance: Dict[str, Any]) -> Dict[str, Any]:
    """Reduce a Subset Sum instance to an equivalent SAT instance.

    The reduction runs in polynomial time and produces a CNF formula that is
    satisfiable exactly when the subset‑sum instance has a solution.
    """
    SubsetSum.validate(instance)
    numbers: List[int] = instance["numbers"]
    target: int = instance["target"]

    if target < 0:
        return {"num_vars": 1, "clauses": [[]]}

    n = len(numbers)
    total_sum = sum(numbers)
    L = max(target.bit_length(), total_sum.bit_length())
    if L == 0:
        L = 1

    builder = CNFBuilder()
    selectors: List[int] = []
    for i in range(n):
        selectors.append(builder.new_var(name=f"x{i}"))

    # current sum bits and carry bits
    cur_sum: Dict[int, Optional[int]] = {}
    cur_carry: Dict[int, Optional[int]] = {0: None}

    for idx, a in enumerate(numbers):
        bits = [(a >> k) & 1 for k in range(L)]
        next_sum: Dict[int, Optional[int]] = {}
        next_carry: Dict[int, Optional[int]] = {}
        for k in range(L):
            a_bit_var = selectors[idx] if bits[k] == 1 else None
            s_in = cur_sum.get(k)
            c_in = cur_carry.get(k, None)
            s_out, c_out = builder.full_adder(s_in, a_bit_var, c_in)
            next_sum[k] = s_out
            if c_out is not None:
                existing = next_carry.get(k + 1)
                next_carry[k + 1] = builder.or_gate(existing, c_out)
        # propagate carries beyond L from previous iteration
        for k, c in cur_carry.items():
            if k >= L:
                next_carry[k] = builder.or_gate(next_carry.get(k), c)
        cur_sum = next_sum
        cur_carry = next_carry

    # Enforce final sum equals target
    for k in range(L):
        sum_bit = cur_sum.get(k)
        carry_bit = cur_carry.get(k)
        final_bit = builder.or_gate(sum_bit, carry_bit)
        target_bit = (target >> k) & 1
        if target_bit == 1:
            builder.force_true(final_bit)
        else:
            builder.force_false(final_bit)
    for k, c in cur_carry.items():
        if k >= L:
            builder.force_false(c)

    sat_instance = {"num_vars": builder.var_counter, "clauses": builder.clauses}
    Sat.validate(sat_instance)
    return sat_instance

